use super::*;

/// The ids a repo store TRACKS — the set `promote` refreshes and `promote --check` compares.
pub fn tracked_ids(store: &Value) -> Vec<String> {
    impls_of(store)
        .iter()
        .filter_map(|i| i.get("id").and_then(Value::as_str).map(str::to_string))
        .collect()
}
